#!/usr/bin/env node
/**
 * Fail-closed witness for the commit that a data network helper is allowed to
 * publish. The commit must identify both its atomic publication transaction
 * and configured pipeline, and it may contain only that pipeline's declared
 * outputs plus deterministic site artifacts regenerated by the publisher.
 */
import { execFileSync } from 'node:child_process';
import { isAbsolute, normalize, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { DATA_PIPELINES } from '../src/config/dataPipelines.js';
import { SITE_PUBLISH_ARTIFACTS } from './lib/site-publish-artifacts.mjs';

const repoRoot = resolve(fileURLToPath(new URL('..', import.meta.url)));
const [requestedPath, revision = 'HEAD'] = process.argv.slice(2);

function fail(message) {
  console.error(`[verify-data-transaction-head] ERROR: ${message}`);
  process.exit(1);
}

function git(args, options = {}) {
  try {
    return execFileSync('git', args, {
      cwd: repoRoot,
      encoding: options.encoding ?? 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
  } catch (error) {
    const detail = String(error?.stderr || error?.message || '').trim();
    fail(`${args.join(' ')} failed${detail ? `: ${detail}` : ''}`);
  }
}

function oneTrailer(message, name) {
  const pattern = new RegExp(`^${name}:[ \\t]*(\\S(?:.*\\S)?)?[ \\t]*$`, 'gm');
  const values = [...message.matchAll(pattern)].map((match) => match[1] || '');
  if (values.length !== 1 || !values[0]) {
    fail(`HEAD must contain exactly one non-empty ${name} trailer`);
  }
  return values[0];
}

function repoRelativePath(value, label) {
  if (typeof value !== 'string' || !value.trim()) fail(`${label} is empty`);
  const absolute = resolve(repoRoot, value);
  const rel = relative(repoRoot, absolute);
  if (!rel || rel.startsWith('..') || isAbsolute(rel)) fail(`${label} is outside the repository`);
  return normalize(rel).replaceAll('\\', '/');
}

if (!/^[A-Za-z0-9._~^/-]+$/.test(revision)) fail('revision has unsupported characters');
git(['rev-parse', '--verify', `${revision}^{commit}`]);
const message = git(['log', '-1', '--format=%B', revision]);
const transactionId = oneTrailer(message, 'Afflatus-Data-Publish');
const pipelineId = oneTrailer(message, 'Afflatus-Data-Pipeline');
if (!/^[A-Za-z0-9._-]+$/.test(transactionId)) fail('Afflatus-Data-Publish has unsupported characters');

const matches = DATA_PIPELINES.filter((pipeline) => pipeline.id === pipelineId);
if (matches.length !== 1) fail(`Afflatus-Data-Pipeline ${JSON.stringify(pipelineId)} is not unique and configured`);
const pipeline = matches[0];
const outputPaths = new Set(pipeline.outputs.map((output) => repoRelativePath(output.path, 'pipeline output')));
const allowedPaths = new Set([
  ...outputPaths,
  ...SITE_PUBLISH_ARTIFACTS.map((path) => repoRelativePath(path, 'site artifact')),
]);

if (requestedPath) {
  const requested = repoRelativePath(requestedPath, 'requested output');
  if (!outputPaths.has(requested)) {
    fail(`${requested} is not a declared output of ${pipelineId}`);
  }
}

const changedRaw = git([
  'diff-tree', '--root', '--no-commit-id', '--name-only', '-r', '-z', revision,
], { encoding: 'utf8' });
const changedPaths = changedRaw.split('\0').filter(Boolean);
if (!changedPaths.length) fail('HEAD has no changed paths');

const unexpected = changedPaths.filter((path) => !allowedPaths.has(path));
if (unexpected.length) {
  fail(`HEAD contains paths outside ${pipelineId}'s publication boundary: ${unexpected.join(', ')}`);
}
if (!changedPaths.some((path) => outputPaths.has(path))) {
  fail(`HEAD changes no declared output of ${pipelineId}`);
}
// Atomic publication means the publisher validated and staged the complete
// candidate group. It does not mean every member must differ byte-for-byte
// from HEAD: an honest zero-order window or unchanged research snapshot can
// legitimately leave one declared output untouched. The transaction trailer,
// configured path boundary, and pipeline validators establish group integrity.
if (requestedPath) {
  const requested = repoRelativePath(requestedPath, 'requested output');
  if (!changedPaths.includes(requested)) {
    fail(`${revision} does not change requested pipeline output ${requested}`);
  }
}

process.stdout.write(`${pipelineId}\n`);
